package com.safebaba.controller;
import org.springframework.security.core.Authentication; import org.springframework.security.access.AccessDeniedException; import com.safebaba.repository.*;
import com.safebaba.dto.AgendamentoDtos; import com.safebaba.model.*; import com.safebaba.service.AgendamentoService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/agendamentos") public class AgendamentoController { private final AgendamentoService s; private final AgendamentoRepository ar; private final PaiRepository pr; private final BabaRepository br; private final com.safebaba.service.UrgenciaScheduler urgencia; public AgendamentoController(AgendamentoService s, AgendamentoRepository ar, PaiRepository pr, BabaRepository br, com.safebaba.service.UrgenciaScheduler urgencia){this.s=s;this.ar=ar;this.pr=pr;this.br=br;this.urgencia=urgencia;} private boolean admin(Authentication a){return a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_ADMIN"));} @GetMapping("/minha-agenda") public List<AgendamentoDtos.Response> minha(Authentication a){ String e=a.getName(); var baba=br.findAll().stream().filter(b->b.getUsuario().getEmail().equalsIgnoreCase(e)).findFirst(); if(baba.isPresent()) return s.porBaba(baba.get().getId()).stream().map(this::map).toList(); var pai=pr.findAll().stream().filter(p->p.getUsuario().getEmail().equalsIgnoreCase(e)).findFirst(); return pai.isEmpty()?List.of():s.porPai(pai.get().getId()).stream().map(this::map).toList(); } @PostMapping public AgendamentoDtos.Response criar(@Valid @RequestBody AgendamentoDtos.Request r, Authentication a){ if(!pr.findById(r.paiId()).map(p->p.getUsuario().getEmail().equalsIgnoreCase(a.getName())).orElse(false)) throw new AccessDeniedException("Acesso negado.");return map(s.criar(r));} @GetMapping("/pai/{paiId}") public List<AgendamentoDtos.Response> pai(@PathVariable Long paiId, Authentication a){ if(!admin(a)&&!pr.findById(paiId).map(p->p.getUsuario().getEmail().equalsIgnoreCase(a.getName())).orElse(false)) throw new AccessDeniedException("Acesso negado.");return s.porPai(paiId).stream().map(this::map).toList();} @GetMapping("/baba/{babaId}") public List<AgendamentoDtos.Response> baba(@PathVariable Long babaId, Authentication a){ if(!admin(a)&&!br.findById(babaId).map(b->b.getUsuario().getEmail().equalsIgnoreCase(a.getName())).orElse(false)) throw new AccessDeniedException("Acesso negado.");return s.porBaba(babaId).stream().map(this::map).toList();} @PatchMapping("/{id}/status") public AgendamentoDtos.Response status(@PathVariable Long id,@RequestParam StatusAgendamento valor, Authentication a){ Agendamento g=ar.findById(id).orElseThrow(()->new IllegalArgumentException("Agendamento não encontrado.")); boolean eBaba=g.getBaba().getUsuario().getEmail().equalsIgnoreCase(a.getName()), ePai=g.getPai().getUsuario().getEmail().equalsIgnoreCase(a.getName()); boolean okBaba=eBaba&&(valor==StatusAgendamento.ACEITO||valor==StatusAgendamento.RECUSADO||valor==StatusAgendamento.CONCLUIDO), okPai=ePai&&valor==StatusAgendamento.CANCELADO; if(!okBaba&&!okPai) throw new AccessDeniedException("Você não pode fazer essa alteração.");if(valor==StatusAgendamento.RECUSADO && g.getObservacoes()!=null && g.getObservacoes().contains("URGENTE")){ urgencia.encaminharProxima(g); return map(ar.findById(id).orElse(g)); } if(valor==StatusAgendamento.CANCELADO && g.getObservacoes()!=null && g.getObservacoes().contains("URGENTE")){ g.getBaba().setDisponivelAgora(true); br.save(g.getBaba()); } return map(s.status(id,valor));} private AgendamentoDtos.Response map(Agendamento a){return new AgendamentoDtos.Response(a.getId(),a.getPai().getId(),a.getBaba().getId(),a.getBaba().getUsuario().getNome(),a.getDataServico(),a.getHoraInicio(),a.getHoraFim(),a.getEndereco(),a.getQuantidadeCriancas(),a.getObservacoes(),a.getStatus());} }
